#!/usr/bin/env bash
# Run all 6 task checks and print a checklist.
# Usage: ./scripts/run-all.sh
# Do not edit this file.
set -u
cd "$(dirname "$0")/.." || exit 1

DONE_COUNT=0
TABLE=""

run_task() {
    # $1 = task number, $2 = label, rest = command
    NUM="$1"
    LABEL="$2"
    shift 2
    OUTPUT=$("$@" 2>&1)
    echo "$OUTPUT"
    echo "------------------------------------------------------------"
    STATUS=$(echo "$OUTPUT" | tail -n 1)
    if [ "$STATUS" = "DONE" ]; then
        DONE_COUNT=$((DONE_COUNT + 1))
    fi
    NAME="$LABEL "
    while [ ${#NAME} -lt 15 ]; do
        NAME="$NAME."
    done
    TABLE="${TABLE}Task $NUM  $NAME $STATUS
"
}

echo "------------------------------------------------------------"
run_task 1 "Hello"        bash scripts/check-hello.sh
run_task 2 "Book"         bash scripts/run-test.sh BookTest Book
run_task 3 "Product"      bash scripts/run-test.sh ProductTest Product
run_task 4 "Constructors" bash scripts/run-test.sh ConstructorTest Book Product
run_task 5 "Shop"         bash scripts/run-test.sh ShopTest Product Shop
run_task 6 "Main"         bash scripts/check-main.sh

echo
echo "CHECKLIST"
printf "%s" "$TABLE"
echo
echo "Done $DONE_COUNT of 6 tasks"
